def main():
    assert len(L16) == 88, len(L16)
    nouns = [r[2] for r in L16]
    prefixes = [r[1] for r in L16]
    slugs = [r[5] for r in L16] + [r[6] for r in L16]
    vendors = [r[0] for r in L16]
    assert len(set(nouns)) == 88, [n for n in nouns if nouns.count(n) > 1]
    assert len(set(prefixes)) == 88, [p for p in prefixes if prefixes.count(p) > 1]
    assert len(set(slugs)) == 176, [s for s in slugs if slugs.count(s) > 1]
    assert len(set(vendors)) == 88, [v for v in vendors if vendors.count(v) > 1]
    for i, row in enumerate(L16):
        assert len(row) == 17, (i, len(row), row[0])
    g14.emit_file(
        g14.ROOT / "mill_plants_ai.py",
        leftover_n=16,
        start=1436,
        svc_ok="leat",
        svc_bad="lade",
        dash_letter="e",
        leftover_words=16,
        ticket0=9700,
        ban="r1435 es-http-bind-drop-leftover; leftover15 ford/creek r1348-r1435; leftover14 canal/reach; leftover13 dam/weir; r875 tempo; r384 otel-forward; PagerDuty orch; Opsgenie alias; r515 Rootly urgency",
        last_ban="r1435 es-http-bind-drop-leftover",
        rows=L16,
        fn="_l16",
    )


if __name__ == "__main__":
    main()
